// One item carrying every RowID already in the triage sheet.
// Fanning out from a single item keeps each source fetch running once.
const seen = new Set();
for (const r of $input.all()) {
  const id = (r.json.RowID || '').toString().trim();
  if (id) seen.add(id);
}
return [{ json: { seen: Array.from(seen), seenCount: seen.size, runAt: new Date().toISOString() } }];

return $input.all().map((it) => {
  const j = it.json;
  const g = j.guid;
  const guid = (g && typeof g === 'object') ? (g['#text'] || g._ || j.link) : (g || j.link);
  const title = (j.title || '').toString();
  const desc = (typeof j.description === 'string' ? j.description : '').toString();
  return { json: {
    title, link: j.link || '', guid,
    posted_raw: j.pubDate || '',
    source: 'AusTender',
    text: (title + ' \u2014 ' + desc),
    search_blob: (title + ' ' + desc).toLowerCase()
  }};
});

// Only pay for a detail-page fetch when the RSS blurb already looks relevant.
// Deliberately loose — the real precision happens in Classify Relevance.
const HINT = /\b(clean|cleaner|janitor|custodial|housekeep|hygiene|guard|security|patrol|concierge|cctv|surveillance|access control|facilit|caretak|ground ?maintenance)\w*/i;
return $input.all().filter((it) => HINT.test((it.json.search_blob || '') + ' ' + (it.json.title || '')));

// Merge the full ATM page text back onto the RSS metadata.
const meta = $('Prefilter (AT)').item.json;
const page = ($json.pageText || '').toString().replace(/\s+/g, ' ').trim();
const body = page.length > 200 ? page.slice(0, 4000) : meta.text;
return { json: {
  title: meta.title,
  link: meta.link,
  guid: meta.guid,
  posted_raw: meta.posted_raw,
  source: 'AusTender',
  text: body,
  search_blob: (meta.title + ' ' + body).toLowerCase()
} };

return $input.all().map((it) => {
  const j = it.json;
  const raw = (typeof j.description === 'string' ? j.description : JSON.stringify(j.description || '')).toString();
  const clean = raw.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/\s+/g, ' ').trim();
  const title = (j.title || '').toString();
  const g = j.guid;
  const guid = (g && typeof g === 'object') ? (g['#text'] || g._ || j.link) : (g || j.link);
  return { json: {
    title, link: j.link || '', guid,
    posted_raw: j.pubDate || '',
    source: 'VendorPanel',
    text: (title + ' \u2014 ' + clean),
    search_blob: (title + ' ' + clean).toLowerCase()
  }};
});

// Brisbane City Council publishes a 3-column table:
//   cell 1 = title (a link) + description paragraph
//   cell 2 = RFx number / Category / Tender type
//   cell 3 = Close (or Release) date + Contact
// The page renders each table twice (one copy carries the Ariba links, and one
// arrives with escaped whitespace), so normalise hard before matching fields.
const BASE = 'https://www.brisbane.qld.gov.au';
const LANDING = BASE + '/business/council-tenders-and-market-led-proposals/current-tenders';

// entities and escaped newlines must go BEFORE field matching, otherwise
// "Tender&nbsp;type" never matches the label "Tender type"
// One copy of the table arrives double-encoded (&amp;nbsp;), so decode twice —
// decoding once leaves a literal "&nbsp;" behind in the text.
const decode = (h) => (h || '')
  .replace(/\\r\\n|\\r|\\n/g, ' ')
  .replace(/&nbsp;|&#160;/gi, ' ')
  .replace(/&#39;|&rsquo;|&lsquo;/gi, "'")
  .replace(/&quot;|&ldquo;|&rdquo;/gi, '"')
  .replace(/&ndash;|&mdash;/gi, '-')
  .replace(/&amp;/gi, '&');
const clean = (h) => decode(decode(h)).replace(/\s+/g, ' ');

const strip = (h) => clean(h).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

const LABELS = 'RFx number|RFx Number|Category|Tender type|Close date|Release date|Contact';
const field = (cellHtml, label) => {
  const t = strip(cellHtml);
  const re = new RegExp(label + '\\s*:\\s*([^]*?)(?=\\s*(?:' + LABELS + ')\\s*:|$)', 'i');
  const m = t.match(re);
  return m ? m[1].replace(/\s+/g, ' ').trim().replace(/[.,;]+$/, '') : '';
};
// contacts run into job titles and phone numbers - keep just the name(s)
const contactName = (v) => v
  .split(/\s+(?:Senior|Category Specialist|Program Director|Phone|Email|Strategic Procurement)\b/i)[0]
  .replace(/\s+/g, ' ').trim();

const rows = [];
for (const it of $input.all()) {
  const html = (it.json.rows || '').toString();
  const cells = (html.match(/<t[dh][^>]*>[^]*?<\/t[dh]>/gi) || []);
  if (cells.length < 2) continue;

  const c0 = cells[0] || '', c1 = cells[1] || '', c2 = cells[2] || '';
  if (/title and description/i.test(strip(c0))) continue;   // header row

  const a = clean(c0).match(/<a[^>]*href=["']([^"']+)["'][^>]*>([^]*?)<\/a>/i);
  const href = a ? a[1] : '';
  let title = a ? strip(a[2]) : '';
  let description = strip(a ? clean(c0).replace(a[0], '') : c0);
  if (!title || /^email contact$/i.test(title) || /^https?:/i.test(title)) {
    title = description.slice(0, 140);
  }
  // when both title and description sit in one cell, drop the repeated title
  if (description.startsWith(title)) description = description.slice(title.length).replace(/^[\s\-–—:]+/, '');

  const ref      = field(c1, 'RFx number') || field(c1, 'RFx Number');
  const category = field(c1, 'Category');
  const ttype    = field(c1, 'Tender type');
  const closeDate   = field(c2, 'Close date');
  const releaseDate = field(c2, 'Release date');
  const contact     = contactName(field(c2, 'Contact'));

  const rowText = strip(html);
  if (rowText.length < 20) continue;

  const isMailto = /mailto:/i.test(href);
  let link = LANDING;
  if (href && !isMailto) link = /^https?:/i.test(href) ? href : BASE + (href.startsWith('/') ? '' : '/') + href;

  const upcoming = !closeDate && !!releaseDate;
  const closed = /\bclosed\b\s*$/i.test(rowText);

  rows.push({
    // normalise the key so the two rendered copies collapse to one
    key: (ref || title).toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 60),
    score: (isMailto ? 2 : 0) + (ttype ? 1 : 0) + (description ? 1 : 0),
    json: {
      title, link,
      guid: 'BCC:' + (ref || title.slice(0, 90)),
      posted_raw: '', source: 'Brisbane City Council',
      ref, bcc_category: category, bcc_type: ttype,
      bcc_close: closeDate || releaseDate, bcc_contact: contact,
      description,
      text: [
        title, description,
        ref ? 'RFx number: ' + ref : '',
        category ? 'Category: ' + category : '',
        ttype ? 'Tender type: ' + ttype : '',
        closeDate ? 'Close date: ' + closeDate : '',
        releaseDate ? 'Release date: ' + releaseDate : '',
        contact ? 'Contact: ' + contact : '',
        'Buyer: Brisbane City Council'
      ].filter(Boolean).join('. '),
      search_blob: (title + ' ' + description + ' ' + category).toLowerCase(),
      _bcc_upcoming: upcoming, _bcc_closed: closed,
      ariba_request: isMailto ? href.replace(/^[^]*?mailto:/i, 'mailto:').split('?')[0] : ''
    }
  });
}

// keep the richest copy of each tender
const best = new Map();
for (const r of rows) {
  const prev = best.get(r.key);
  if (!prev || r.score > prev.score) best.set(r.key, r);
}
return Array.from(best.values()).filter((r) => !r.json._bcc_closed).map((r) => ({ json: r.json }));

// Sheet-driven watchlist: one row per site (SiteName | URL | Selector).
// Adding a new council or university is a spreadsheet row, not a new node.
const KW = ['security','cleaning','cleaner','guard','patrol','janitor','custodial','concierge','cctv','surveillance','housekeeping'];
const out = [];
for (const row of $input.all()) {
  const site = (row.json.SiteName || 'Watchlist').toString().trim();
  const url = (row.json.URL || '').toString().trim();
  if (!url || !/^https?:/i.test(url)) continue;
  let html = '';
  try {
    const res = await this.helpers.httpRequest({ url, headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' }, timeout: 25000 });
    html = (typeof res === 'string') ? res : JSON.stringify(res);
  } catch (e) { continue; }
  const om = url.match(/^https?:\/\/[^/]+/);
  const origin = om ? om[0] : '';
  const re = /<a[^>]*href=["']([^"'#]+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let m; const seen = new Set();
  while ((m = re.exec(html)) !== null) {
    let link = m[1];
    const title = m[2].replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/\s+/g, ' ').trim();
    if (title.length < 15) continue;
    const blob = title.toLowerCase();
    if (!KW.some((k) => blob.includes(k))) continue;
    if (link.startsWith('/')) link = origin + link;
    if (!/^https?:/i.test(link)) continue;
    if (seen.has(link)) continue;
    seen.add(link);
    out.push({ json: { title, link, guid: 'WL:' + link, posted_raw: '', source: site, text: title, search_blob: blob } });
  }
}
return out;

// Items pushed in by the Apify / Playwright robot (or any external fetcher).
// Expected shape: title, link, guid, source, text.
const body = $input.first().json;
const arr = Array.isArray(body) ? body : (Array.isArray(body.body) ? body.body : [body]);
return arr.filter(Boolean).map((j) => {
  const title = (j.title || '').toString();
  const text = (j.text || title).toString();
  return { json: {
    title, link: j.link || '', guid: j.guid || ('PUSH:' + (j.link || title)),
    posted_raw: j.posted_raw || '', source: j.source || 'Robot',
    text, search_blob: (j.search_blob || (title + ' ' + text)).toLowerCase()
  }};
});

return $input.all().map((it) => {
  const j = it.json;
  const subject = (j.subject || '').toString();
  const body = (j.textPlain || j.textHtml || j.text || '').toString().replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const linkM = body.match(/https?:\/\/[^\s"'<>]+/);
  return { json: {
    title: subject,
    link: linkM ? linkM[0] : '',
    guid: 'MAIL:' + (j.messageId || subject).toString().slice(0, 120),
    posted_raw: j.date || '',
    source: 'Tender Inbox',
    text: (subject + ' \u2014 ' + body).slice(0, 6000),
    search_blob: (subject + ' ' + body).toLowerCase()
  }};
});

// === RELEVANCE CLASSIFIER (all sources) ===
// Tags every item _keep / _drop_reason. Nothing is discarded here so the
// rejection log can record what we dropped and why.
const NEG = /\b(biosecurity|cyber ?security|information security|info security|it security|data security|food security|national security|network security)\b/i;

const STRONG = /\b(cleaning|cleaner|janitor|janitorial|housekeeping|custodial|hygiene services|guard|guarding|security guard|security service|security officer|manned guarding|static guard|crowd control|mobile patrol|patrol|concierge|cctv|surveillance|access control|alarm response|alarm monitoring|loss prevention|gatehouse)\b/i;

const CLEAN_BAD = /\b(hull|street sweep|drain|pipe|duct|tank|dry clean|desludg)\b/i;
const FACIL = /\bfacilit(?:y|ies) (?:management|manager|cleaning|maintenance|services)\b/i;
const CAT_GOOD = /(security services|cleaning services|security & monitoring|building cleaning)/i;

const OTHER = /\b(construction|demolition|demolish|refurbish\w*|redevelopment|design and construct|design & construct|building works|amenities building|change ?room|swimming pool|aquatic centre|landfill|kerbside|waste collection|recycl\w+|pavement|road upgrade|intersection|switchboard|hvac|air ?condition\w*|solar|lift (replacement|maintenance)|childcare|long day care|graphic design|physiotherapy|aquaponics|tree pruning|weed spraying|planning scheme|irrigation|generator maintenance)\b/i;

const catText = (t) => { const m = (t || '').toLowerCase().match(/tender categories\s*:\s*([^]*?)(specification docs|$)/); return m ? m[1] : ''; };

return $input.all().map((it) => {
  const j = it.json;
  const title = (j.title || '').toString();
  const blob  = (j.search_blob || j.text || '').toString().toLowerCase();
  const cats  = catText((j.text || '').toString());

  let keep = false, reason = '';

  if (NEG.test(blob)) { reason = 'cyber/bio-security, not physical security'; }
  else if (STRONG.test(title) && !(CLEAN_BAD.test(title) && !/\b(guard|security|cctv|patrol)\b/i.test(title))) { keep = true; }
  else if (FACIL.test(title)) { keep = true; }
  else if (OTHER.test(blob)) { reason = 'construction / other trade, not a security or cleaning service'; }
  else if (CAT_GOOD.test(cats)) { keep = true; }
  else if (STRONG.test(blob)) { keep = true; }
  else { reason = 'no security or cleaning service term found'; }

  j._keep = keep;
  j._drop_reason = reason;
  j._stage = 'keyword';
  return { json: j };
});

// Alerts if a source that should always return rows returned none —
// catches silent scrape breakage, which otherwise looks like a quiet week.
const EXPECTED = ['AusTender', 'VendorPanel', 'Brisbane City Council'];
const counts = {};
for (const it of $input.all()) {
  const s = (it.json.source || 'unknown').toString();
  counts[s] = (counts[s] || 0) + 1;
}
const missing = EXPECTED.filter((s) => !counts[s]);
const summary = Object.entries(counts).map(([k, v]) => k + ': ' + v).join('  |  ') || 'nothing returned by any source';
return [{ json: { counts, missing, unhealthy: missing.length > 0, summary, missingList: missing.join(', ') } }];

// Dedupe against the RowIDs already in the sheet (survives re-imports and
// manual runs, unlike workflow static data) plus within this batch.
let seen = new Set();
try { seen = new Set(($('Collect Seen IDs').first().json.seen) || []); } catch (e) {}
const batch = new Set();
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  const id = (j.guid || j.link || j.title || '').toString().slice(0, 180).replace(/[\t\n]/g, ' ');
  if (!id) continue;
  if (seen.has(id) || batch.has(id)) continue;
  batch.add(id);
  j.RowID = id;
  out.push({ json: j });
}
return out;

let raw = ($json.text || '').toString().replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { parsed = { tier: 'Reject', parse_error: true }; }
const meta = $('Dedupe vs Sheet').item.json;
return { json: {
  RowID: meta.RowID, title: meta.title, link: meta.link, source: meta.source,
  posted_raw: meta.posted_raw, ariba_request: meta.ariba_request || '',
  ref: meta.ref || '',
  category: meta.bcc_category || '',
  tender_type: meta.bcc_type || '',
  source_text: (meta.description || meta.text || '').toString(),
  ...parsed
} };

