const norm = (s) => (s || '').toString().toLowerCase();
const INTERSTATE = ['nsw','vic','sa','wa','tas','nt','act','new south wales','victoria','tasmania'];

return $input.all().map((item) => {
  const j = item.json;
  let inzone = '', reason = '';

  if (!['A','B','C'].includes(j.tier)) {
    reason = 'LLM tier = ' + (j.tier || 'none');
  } else {
    const region = norm(j.region), state = norm(j.state), loc = norm(j.location_text);
    if (region === 'interstate' || INTERSTATE.includes(state)) {
      reason = 'interstate (' + (j.state || j.region) + ')';
    } else {
      if (KEEP_STATEWIDE && region === 'qld-statewide') inzone = 'Statewide';
      if (!inzone) {
        const found = (loc.match(/\b4\d{3}\b/g) || []);
        if (found.some((pc) => POSTCODES.has(pc))) inzone = 'Yes (postcode)';
      }
      if (!inzone) {
        for (const sub of SUBURBS) {
          if (sub.length < 4) continue;
          const re = new RegExp('(^|[^a-z])' + sub.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '([^a-z]|$)');
          if (re.test(loc)) { inzone = 'Yes (suburb)'; break; }
        }
      }
      if (!inzone) reason = 'outside 50km zone (' + (j.location_text || 'no location') + ')';
    }
  }

  if (inzone && inzone.startsWith('Yes')) j.region = 'SEQ';
  j.InZone = inzone;
  j._keep = !!inzone;
  j._drop_reason = reason;
  j._stage = 'zone/tier';
  return { json: j };
});

