return $input.all().map((it) => {
  const j = it.json;
  const rel = (j.text || '').match(/release date\s*:?\s*([A-Za-z]+\s*\d{4}|TBC|TBA)/i);
  const cat = (j.text || '').match(/category\s*:?\s*([^]*?)(release date|tender type|contact|$)/i);
  return { json: {
    Logged: ts,
    Source: j.source || 'Brisbane City Council',
    Title: j.title || '',
    Ref: j.ref || '',
    Category: cat ? cat[1].replace(/\s+/g, ' ').trim().slice(0, 120) : '',
    ExpectedRelease: rel ? rel[1].trim() : '',
    Link: j.link || '',
    Detail: (j.text || '').toString().slice(0, 500)
  }};
});
